from flask import Flask, request, jsonify
import subprocess

app = Flask(__name__)

@app.route('/add', methods=['POST'])
def add():
    x = request.form['x']
    y = request.form['y']

    proc = subprocess.Popen(['python', '/app/add.py', x, y], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = proc.communicate()
    result = stdout.decode()

    return jsonify(result)

if __name__ == '__main__':
    app.run()
